css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); display: grid; place-items: center; }
.loader .shaker { position: relative; width: 40%; height: 70%; overflow: hidden; border-radius: 12% 12% 20% 20%; background: linear-gradient(100deg, color-mix(in srgb, #fff 38%, var(--accent-2)), var(--accent-2)); box-shadow: inset calc(var(--loader-size) * -.03) 0 calc(var(--loader-size) * .05) rgba(15, 23, 42, .3); animation: shake calc(var(--loader-speed) * .9) ease-in-out infinite; }
.loader .shaker::after { content: ''; position: absolute; top: 0; left: 10%; width: 80%; height: 16%; border-radius: 4px 4px 8px 8px; background: linear-gradient(var(--accent), color-mix(in srgb, #000 28%, var(--accent))); }
.loader .shaker span { position: absolute; width: 30%; height: 24%; border-radius: 3px; background: rgba(255, 255, 255, .68); animation: slosh calc(var(--loader-speed) * .9) ease-in-out infinite; }
.loader .shaker span:nth-child(1) { bottom: 12%; left: 14%; }
.loader .shaker span:nth-child(2) { bottom: 34%; left: 44%; animation-delay: calc(var(--loader-speed) * .3); }
@keyframes shake { 0%, 100% { transform: rotate(-17deg) translateY(0); } 25% { transform: rotate(15deg) translateY(-7%); } 50% { transform: rotate(-15deg) translateY(0); } 75% { transform: rotate(17deg) translateY(-7%); } }
@keyframes slosh { 0%, 100% { transform: translate(-12%, 0); } 50% { transform: translate(32%, -42%); } }
